import { Box, Button, Typography } from "@mui/material";
import type { HomeCta } from "../types/home";

export default function ExamCta({ data }: { data?: HomeCta | null }) {
  if (!data?.title && !data?.buttonUrl) return null;

  return (
    <Box sx={{ textAlign: "center", py: 6 }}>
      {data.title ? (
        <Typography sx={{ color: "#17224d", fontSize: { xs: 26, md: 36 }, fontWeight: 600, mb: 3 }}>
          {data.title}
        </Typography>
      ) : null}
      {data.buttonUrl ? (
        <Button
          variant="contained"
          href={data.buttonUrl}
          target="_blank"
          rel="noopener noreferrer"
          sx={{
            backgroundColor: "#759ae1",
            px: 4,
            py: 1.2,
            borderRadius: "6px",
            "&:hover": { backgroundColor: "#5f86d4" },
          }}
        >
          {data.buttonLabel || "Subscribe Now"}
        </Button>
      ) : null}
    </Box>
  );
}
